import {Pressable,Text,View} from "react-native";
import {joinClasses} from "@/components/nyc-tron/ui/components/styles";
import {space,radius,opacity,size} from "@/components/nyc-tron/ui/tokens";

/**
 * Labeled on/off row shared by the canvas settings panels: a 44pt switch with
 * the label on the start side and the track on the end side (mirrored in RTL).
 */
export function SettingSwitch({label,on,onChange,disabled,styled,hint}:{
  label:string;on:boolean;onChange:(on:boolean)=>void;disabled:boolean;styled:boolean;hint?:string|undefined;
}){
  return <Pressable role="switch" aria-checked={on} accessibilityRole="switch" accessibilityState={{checked:on,disabled}}
    aria-label={label} accessibilityHint={hint} disabled={disabled} onPress={()=>onChange(!on)}
    {...{className:joinClasses(styled&&"rounded-control focus-visible:ring-2 focus-visible:ring-focus")}}
    style={{minHeight:size.touch,flexDirection:"row",alignItems:"center",justifyContent:"space-between",gap:space[3],paddingHorizontal:space[1],opacity:disabled?opacity[50]:1}}>
    <Text {...{className:joinClasses(styled&&"text-text text-sm")}} style={{flexShrink:1}}>{label}</Text>
    <View pointerEvents="none" {...{className:joinClasses(styled&&"border",styled&&(on?"bg-primary border-primary":"bg-surface-sunken border-border"))}}
      style={{width:40,height:24,borderRadius:radius[12],padding:space[0.5],justifyContent:"center",alignItems:on?"flex-end":"flex-start"}}>
      <View {...{className:joinClasses(styled&&(on?"bg-on-primary":"bg-text-muted"))}} style={{width:18,height:18,borderRadius:radius[9]}}/>
    </View>
  </Pressable>;
}

import {View} from 'react-native';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {validateMotionVector,type MotionVector3} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
import {space} from '@/components/nyc-tron/ui/tokens';
export interface MotionVectorFieldsProps {readonly label:string;readonly value:MotionVector3;readonly onCommit:(value:MotionVector3)=>void;readonly min?:number;readonly max?:number;readonly step?:number;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Common axis entry preserves the two untouched floating coordinates. */
export function MotionVectorFields({label,value,onCommit,min=-1e9,max=1e9,step=1,disabled=false,unstyled=false}:MotionVectorFieldsProps){
 validateMotionVector(value,min,max);return <View style={{gap:space[1.5]}}>{(['x','y','z'] as const).map(axis=><UnitInput key={axis} label={`${label} ${axis.toUpperCase()}`} value={value[axis]} min={min} max={max} step={step} precision={6} disabled={disabled} unstyled={unstyled} onCommit={number=>{if(disabled||number===value[axis])return;const next={...value,[axis]:number};validateMotionVector(next,min,max);onCommit(next);}}/>)}</View>;
}

import {View,type ViewProps} from 'react-native';
import {Select} from '@/components/nyc-tron/ui/components/Select';
import {UnitInput} from '@/components/nyc-tron/ui/components/shell/UnitInput';
import {SettingSwitch} from '@/components/nyc-tron/ui/components/forge/canvas/SettingSwitch';
import {MotionVectorFields} from '@/components/nyc-tron/ui/components/forge/motion/MotionVectorFields';
import {validateMotionParticles,type MotionParticleEmitter} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
import {space} from '@/components/nyc-tron/ui/tokens';
export type {MotionParticleEmitter} from '@/components/nyc-tron/ui/components/forge/motion/motion-settings';
export interface ParticleEmitterControlsProps extends Omit<ViewProps,'children'> {readonly value:MotionParticleEmitter;readonly textures:readonly {readonly id:string;readonly label:string}[];readonly onCommit:(value:MotionParticleEmitter)=>void;readonly disabled?:boolean;readonly unstyled?:boolean}
/** Deterministic emitter settings; the compositor owns particle simulation and texture resources. */
export function ParticleEmitterControls({value,textures,onCommit,disabled=false,unstyled=false,...props}:ParticleEmitterControlsProps){
 validateMotionParticles(value);const ids=new Set<string>();for(const texture of textures){if(!texture.id.trim()||!texture.label.trim()||ids.has(texture.id))throw new TypeError('Particle textures require unique identities');ids.add(texture.id);}
 const set=(change:Partial<MotionParticleEmitter>)=>{if(disabled)return;const next={...value,...change};validateMotionParticles(next);onCommit(next);};
 const options=[{value:'',label:'No texture'},...textures.map(texture=>({value:texture.id,label:texture.label}))];if(value.textureId!==null&&!ids.has(value.textureId))options.push({value:value.textureId,label:`Unavailable texture: ${value.textureId}`});
 return <View {...props} style={[{gap:space[2]},props.style]}>
  <SettingSwitch label="Enable particle emitter" on={value.enabled} onChange={enabled=>set({enabled})} disabled={disabled} styled={!unstyled}/>
  {([['rate','Particles per second',0,100000,1],['lifetime','Particle lifetime seconds',.001,86400,.1],['speed','Particle initial speed',0,1e6,1],['spreadDegrees','Particle spread degrees',0,360,1],['size','Particle size',.001,100000,1],['opacity','Particle opacity',0,1,.01],['seed','Particle random seed',0,4294967295,1]] as const).map(([key,label,min,max,step])=><UnitInput key={key} label={label} value={value[key]} min={min} max={max} step={step} precision={key==='seed'?0:3} disabled={disabled} unstyled={unstyled} onCommit={number=>set({[key]:key==='seed'?Math.round(number):number})}/>)}
  <MotionVectorFields label="Particle gravity" value={value.gravity} min={-100000} max={100000} step={.1} disabled={disabled} unstyled={unstyled} onCommit={gravity=>set({gravity})}/>
  <Select label="Particle texture" value={value.textureId??''} options={options} disabled={disabled} unstyled={unstyled} onValueChange={textureId=>set({textureId:textureId||null})}/>
 </View>;
}

/**
 * Tailwind classes are merged at the APP boundary. Joining without
 * tailwind-merge avoids deleting custom typography/color utilities that
 * depend on each consumer's own @theme configuration.
 */
export function joinClasses(...items: Array<string|false|null|undefined>):string {
  return items.filter(Boolean).join(" ");
}

